public int prims(int n, int[][] edges, int start) {
    List<List<int[]>> adj = new ArrayList<>();
    for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
    for (int[] e : edges) {
        adj.get(e[0]).add(new int[]{e[1], e[2]});
        adj.get(e[1]).add(new int[]{e[0], e[2]});   // undirected
    }
    long[] key = new long[n + 1];
    Arrays.fill(key, Long.MAX_VALUE);
    key[start] = 0;
    boolean[] inTree = new boolean[n + 1];
    long total = 0;
    for (int iter = 0; iter < n; iter++) {
        int u = -1;
        long best = Long.MAX_VALUE;
        for (int i = 1; i <= n; i++) {
            if (!inTree[i] && key[i] < best) { best = key[i]; u = i; }
        }
        if (u == -1) break;             // disconnected (shouldn't happen here)
        inTree[u] = true;
        total += key[u];
        for (int[] edge : adj.get(u)) {
            int v = edge[0], w = edge[1];
            if (!inTree[v] && w < key[v]) key[v] = w;   // relax on EDGE weight
        }
    }
    return (int) total;
}

