def prims(self, n: int, edges: list[list[int]], start: int) -> int:
    adj: list[list[tuple[int, int]]] = [[] for _ in range(n + 1)]
    for u, v, w in edges:
        adj[u].append((v, w))
        adj[v].append((u, w))            # undirected
    INF = float('inf')
    key = [INF] * (n + 1)
    key[start] = 0
    in_tree = [False] * (n + 1)
    total = 0
    for _ in range(n):
        u, best = -1, INF
        for i in range(1, n + 1):
            if not in_tree[i] and key[i] < best:
                best, u = key[i], i
        if u == -1:
            break                        # disconnected
        in_tree[u] = True
        total += key[u]
        for v, w in adj[u]:
            if not in_tree[v] and w < key[v]:
                key[v] = w                # relax on EDGE weight, not path cost
    return total

