public int prims(int n, int[][] edges, int start) {
    List<List<int[]>> adj = new ArrayList<>();
    for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
    for (int[] e : edges) {
        adj.get(e[0]).add(new int[]{e[1], e[2]});
        adj.get(e[1]).add(new int[]{e[0], e[2]});   // undirected
    }
    long[] dist = new long[n + 1];
    Arrays.fill(dist, Long.MAX_VALUE);
    dist[start] = 0;
    boolean[] inTree = new boolean[n + 1];
    PriorityQueue<long[]> heap = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
    heap.offer(new long[]{0, start});
    long total = 0;
    while (!heap.isEmpty()) {
        long[] top = heap.poll();
        long w = top[0];
        int u = (int) top[1];
        if (inTree[u]) continue;            // stale duplicate
        inTree[u] = true;
        total += w;
        for (int[] edge : adj.get(u)) {
            int v = edge[0], wt = edge[1];
            if (!inTree[v] && wt < dist[v]) {
                dist[v] = wt;               // cheapest crossing edge to v
                heap.offer(new long[]{wt, v});
            }
        }
    }
    return (int) total;
}

